package network.velora.mobile;
import com.getcapacitor.*;import com.getcapacitor.annotation.CapacitorPlugin;import android.content.*;import android.net.Uri;import android.os.Build;import androidx.core.content.FileProvider;import java.net.*;import java.io.*;import java.security.MessageDigest;import java.util.concurrent.*;import org.json.*;
@CapacitorPlugin(name="VeloraUpdates")
public class NativeUpdatePlugin extends Plugin {
 private JSObject state=new JSObject();private JSONObject asset;private File downloaded;private final ExecutorService executor=Executors.newSingleThreadExecutor();
 private String appId(){String id=getContext().getPackageName();return id.substring(id.lastIndexOf('.')+1);}
 private boolean allowed(){try{JSONObject n=new JSONObject(getContext().getSharedPreferences("velora-native",0).getString("network","{}"));return n.optBoolean("online",false)&&n.optJSONObject("features").optBoolean("updates",true);}catch(Exception e){return false;}}
 @Override public void load(){state.put("status","idle");state.put("progress",0);state.put("manual",true);try{state.put("version",getContext().getPackageManager().getPackageInfo(getContext().getPackageName(),0).versionName);}catch(Exception ignored){} }
 private void emit(String status){state.put("status",status);notifyListeners("state",state);}
 private boolean source(URL url){String h=url.getHost();return url.getProtocol().equals("https")&&url.getUserInfo()==null&&(h.equals("github.com")&&url.getPath().startsWith("/coldzeeyt/nexora/releases/")||h.equals("release-assets.githubusercontent.com")||h.equals("objects.githubusercontent.com"));}
 private HttpURLConnection fetch(String value)throws Exception{URL url=new URL(value);for(int n=0;n<5;n++){if(!source(url))throw new Exception("Invalid update source.");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(45000);int code=c.getResponseCode();if(code>=300&&code<400){url=new URL(url,c.getHeaderField("Location"));c.disconnect();continue;}if(code!=200){c.disconnect();throw new Exception("Update unavailable.");}return c;}throw new Exception("Too many redirects.");}
 private String hex(byte[] bytes){StringBuilder value=new StringBuilder();for(byte b:bytes)value.append(String.format("%02x",b&255));return value.toString();}
 @PluginMethod public void run(PluginCall call){executor.execute(()->{try{String operation=call.getString("operation","status");if(operation.equals("status")){call.resolve(state);return;}if(operation.equals("install")&&downloaded!=null){if(Build.VERSION.SDK_INT>=26&&!getContext().getPackageManager().canRequestPackageInstalls()){Intent settings=new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getContext().getPackageName()));getActivity().startActivity(settings);state.put("error","Allow installs from this app in Android Settings, then tap Open update installer again.");}else{Uri uri=FileProvider.getUriForFile(getContext(),getContext().getPackageName()+".fileprovider",downloaded);Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);getActivity().startActivity(intent);state.put("error","Confirm the update in Android’s installer.");}call.resolve(state);return;}if(!allowed()){emit("offline");state.put("error","Enable Online mode and updates in Settings.");call.resolve(state);return;}state.remove("error");if(operation.equals("check")){emit("checking");HttpURLConnection c=fetch("https://github.com/coldzeeyt/nexora/releases/latest/download/"+appId()+"-android.json");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[8192];try(InputStream in=c.getInputStream()){int n;while((n=in.read(buffer))!=-1){out.write(buffer,0,n);if(out.size()>20000)throw new Exception("Invalid update manifest.");}}finally{c.disconnect();}JSONObject m=new JSONObject(out.toString("UTF-8"));String version=m.getString("version");if(!version.matches("[0-9]+\\.[0-9]+\\.[0-9]+")||!m.getString("packageId").equals(getContext().getPackageName())||!m.getString("sha256").matches("[0-9a-f]{64}")||!m.getString("url").startsWith("https://github.com/coldzeeyt/nexora/releases/download/")||!m.getString("url").endsWith(".apk")||m.getLong("size")<1||m.getLong("size")>200*1024*1024)throw new Exception("Invalid update manifest.");asset=m;int code=getContext().getPackageManager().getPackageInfo(getContext().getPackageName(),0).versionCode;state.put("availableVersion",version);emit(m.getInt("versionCode")>code?"available":"current");}else if(operation.equals("download")&&asset!=null){emit("downloading");File temp=new File(getContext().getCacheDir(),"velora-update.part");HttpURLConnection c=fetch(asset.getString("url"));MessageDigest hash=MessageDigest.getInstance("SHA-256");long size=0;try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(temp)){byte[] bytes=new byte[32768];int n;while((n=in.read(bytes))!=-1){if(!allowed())throw new Exception("Updates disabled.");size+=n;if(size>asset.getLong("size"))throw new Exception("Invalid update size.");hash.update(bytes,0,n);out.write(bytes,0,n);state.put("progress",(int)(size*100/asset.getLong("size")));notifyListeners("state",state);}}finally{c.disconnect();}if(size!=asset.getLong("size")||!hex(hash.digest()).equals(asset.getString("sha256"))){temp.delete();throw new Exception("Update integrity check failed.");}android.content.pm.PackageManager pm=getContext().getPackageManager();android.content.pm.PackageInfo installed=pm.getPackageInfo(getContext().getPackageName(),Build.VERSION.SDK_INT>=28?android.content.pm.PackageManager.GET_SIGNING_CERTIFICATES:android.content.pm.PackageManager.GET_SIGNATURES);android.content.pm.PackageInfo archive=pm.getPackageArchiveInfo(temp.getAbsolutePath(),Build.VERSION.SDK_INT>=28?android.content.pm.PackageManager.GET_SIGNING_CERTIFICATES:android.content.pm.PackageManager.GET_SIGNATURES);if(archive==null||!archive.packageName.equals(installed.packageName)||archive.versionCode<=installed.versionCode||!java.util.Arrays.equals((Build.VERSION.SDK_INT>=28?installed.signingInfo.getApkContentsSigners():installed.signatures)[0].toByteArray(),(Build.VERSION.SDK_INT>=28?archive.signingInfo.getApkContentsSigners():archive.signatures)[0].toByteArray())){temp.delete();throw new Exception("The update signing certificate does not match this app.");}downloaded=new File(getContext().getCacheDir(),"velora-update.apk");if(!temp.renameTo(downloaded))throw new Exception("Could not save the update.");state.put("progress",100);emit("downloaded");}call.resolve(state);}catch(Exception e){state.put("error",e.getMessage()==null?"Could not update the app.":e.getMessage());emit("error");call.resolve(state);}});}
}
